{"command": "python3 -c "
from PIL import Image
im=Image.open('radiograph.jpg')
W,H=im.size
bands={
 'max': (0.30,0.52),
 'mand':(0.68,0.95),
}
xs={'L':(0.10,0.42),'M':(0.36,0.66),'R':(0.60,0.95)}
for bn,(y0,y1) in bands.items():
    for xn,(x0,x1) in xs.items():
        box=(int(x0*W),int(y0*H),int(x1*W),int(y1*H))
        cr=im.crop(box)
        cr=cr.resize((cr.width*2,cr.height*2),Image.LANCZOS)
        cr.save(f'/app/band_{bn}_{xn}.png')
        print(bn,xn,box,cr.size)
